import {renderLab,stopLab} from './lab.js';
import {freshProgress,cleanProgress,equal} from './progress.js';
export function bootCourse(store) {
const {units,extra}=window.COURSE;
const $=(q,root=document)=>root.querySelector(q);
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={route:'M4 19h4l4-14h8 M5 5h3 M17 19h3',book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z M20 4h-5a3 3 0 0 0-2 3v14a4 4 0 0 1 4-2h3z',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3 M8 22h8',repeat:'M3 10a9 9 0 0 1 15-6l3 3 M21 2v5h-5 M21 14a9 9 0 0 1-15 6l-3-3 M3 22v-5h5',chart:'M4 20V10 M10 20V4 M16 20v-8 M22 20H2',headphones:'M4 15v-3a8 8 0 0 1 16 0v3 M4 13h3v8H4z M17 13h3v8h-3z',check:'M5 12l4 4L20 5',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',star:'m12 3 3 6 6 1-4.5 4.5 1 6-5.5-3-5.5 3 1-6L3 10l6-1z',flame:'M12 2c1 6 7 7 7 13a7 7 0 0 1-14 0c0-4 2-7 4-9v6c3-2 3-6 3-10z',play:'m8 4 12 8-12 8z',volume:'M3 9h4l5-5v16l-5-5H3z M16 8a6 6 0 0 1 0 8 M19 5a10 10 0 0 1 0 14',close:'M5 5l14 14 M19 5 5 19',chevron:'m9 5 7 7-7 7',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c-5 5-5 13 0 18 M12 3c5 5 5 13 0 18',pen:'m4 16 12-12 4 4L8 20H4z M14 6l4 4',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.book}"/></svg>`;
const day=()=>new Date().toLocaleDateString('en-CA');
const defaults=freshProgress;
let knownQuestions;
function hydrateProgress(raw){const p=cleanProgress(raw);if(knownQuestions)p.errors=Object.fromEntries(Object.keys(p.errors).filter(k=>knownQuestions.has(k)).map(k=>[k,knownQuestions.get(k)]));return p;}
let state=hydrateProgress(store.getState()),storageOK=true;
function save(){store.save(state);storageOK=store.localAvailable;}
function activity(n=1){state.activity[day()]=(state.activity[day()]||0)+n;save();}
function streak(){let n=0,d=new Date();if(!state.activity[day()])d.setDate(d.getDate()-1);for(let i=0;i<3660;i++){if(!state.activity[d.toLocaleDateString('en-CA')])break;n++;d.setDate(d.getDate()-1);}return n;}
const done=()=>Object.keys(state.completed).filter(k=>/^\d+_[012]$/.test(k)).length;
const uDone=id=>[0,1,2].filter(i=>state.completed[`${id}_${i}`]).length;
const nextLesson=()=>{for(const u of units)for(let i=0;i<3;i++)if(!state.completed[`${u.id}_${i}`])return[u,i];return[units[0],0];};
const vocab=[...new Map([...units.flatMap(u=>u.vocab.map((v,i)=>({...v,unit:u.id,key:`u${u.id}v${i}`}))),...['colours','jobs','animals'].flatMap(k=>extra[k].map((x,i)=>({en:x[0],es:x[1],icon:x[2],unit:0,key:`${k}${i}`}))),...Object.entries(extra.packs||{}).flatMap(([group,words],g)=>words.map((x,i)=>({en:x[0],es:x[1],icon:x[2],unit:0,group,key:`pack${g}v${i}`})))].map(v=>[v.en.toLowerCase()+'|'+v.es,v])).values()];
const navs=[['route','route','Mi ruta'],['vocab','book','Vocabulario'],['lab','mic','Voz y sonidos'],['review','repeat','Repasar'],['library','headphones','Biblioteca A1'],['progress','chart','Mi progreso']];
let current='route',session=null,voiceIndex=0,voiceUnit=0,recognition=null,recording=false,transcript='',speechResult=null,voiceMsg='',filterVocab='',searchVocab='',flash=null,lessonStage='learn',tab='words',libraryTab='guide';
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4200);}
function stopAudio(){if('speechSynthesis'in window)window.speechSynthesis.cancel();if(recognition){recognition.onend=null;recognition.abort();recognition=null;}recording=false;}
function speak(text,rate=0.85){if(!('speechSynthesis'in window)){toast('Tu navegador no ofrece lectura en voz alta. Puedes leer el texto.');return;}window.speechSynthesis.cancel();const s=new SpeechSynthesisUtterance(text);s.lang=state.accent;s.rate=rate;const voices=window.speechSynthesis.getVoices();s.voice=voices.find(v=>v.lang===state.accent)||voices.find(v=>v.lang.startsWith('en'))||null;s.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('No se pudo reproducir la voz. Revisa las voces instaladas o prueba otro navegador.');};window.speechSynthesis.speak(s);}
const sound=(text,small=false)=>`<button class="${small?'sound':'btn soft'}" data-say="${esc(text)}" aria-label="Escuchar: ${esc(text)}">${icon('volume')}${small?'':'Escuchar'}</button>`;
function nav(route){location.hash=route;if(location.hash.slice(1)===route)routeChanged();}
function shell(html,title='Tu espacio de aprendizaje',sub='INGLÉS DESDE CERO'){
 const active=['unit','lesson','exam'].includes(current)?'route':['practice','cards'].includes(current)?'review':current;
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#home"><span class="brand-mark">h<span>!</span></span><span>Hello<span class="brand-a1">A1</span><small>English, at your pace</small></span></a><div class="level-pill">${icon('globe')} Español <span>·</span> Inglés A1</div><div class="level-switch" aria-label="Elegir nivel"><button data-level="a1" aria-current="true">A1</button><button data-level="a2" >A2</button><button data-level="b1" >B1</button></div><nav aria-label="Navegación principal">${navs.map(([r,i,t])=>`<a href="#${r}" class="nav-item ${active===r?'active':''}" ${active===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${r==='review'&&Object.keys(state.errors).length?`<b>${Object.keys(state.errors).length}</b>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="mini-note">${icon('star')} Tu ritmo. Tu camino.<small>Sin vidas que perder.<br>Equivocarte también cuenta.</small></div><a href="#account" class="profile"><span class="avatar">${esc((state.name||'T')[0].toUpperCase())}</span><span>${esc(state.name||'Tu espacio')}<small>${store.user?'Mi cuenta y guardado':'Entrar con Google'}</small></span>${icon('settings')}</a></div></aside><div class="workspace"><header class="topbar"><span class="top-label">${icon('globe')} English, one step at a time</span><div class="top-stats"><span title="Días consecutivos de práctica">${icon('flame')} <b>${streak()}</b> <span class="stat-caption">días</span></span><span title="Puntos ganados">${icon('star')} <b>${state.xp}</b> <span class="stat-caption">XP</span></span><button class="account-chip" data-action="nav" data-to="account" data-account-badge aria-label="Abrir mi cuenta">${accountBadge()}</button></div></header><main id="main" tabindex="-1"><div class="page-heading"><div><p class="eyebrow">${sub}</p><h1>${title}</h1></div>${current==='route'?`<button class="btn ghost" data-action="print-guide">${icon('book')} Guía completa</button>`:''}</div>${!storageOK?'<div class="notice">El guardado local está limitado. Puedes exportar tus avances desde Mi progreso.</div>':''}${html}</main><footer>Hecho para aprender, paso a paso. <a href="#library/method">Método y fuentes</a><span> · </span><a href="#library/privacy">Voz y privacidad</a></footer></div>`;
}
function percentBar(n){return`<div class="progress-track" role="progressbar" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="100"><i style="width:${n}%"></i></div>`;}
const blockNames=['Primeras conversaciones','Tu vida, en inglés','Sal al mundo','Conecta tus ideas'];
function renderRoute(){const [next,idx]=nextLesson(),today=state.activity[day()]||0,pct=Math.round(done()/72*100);const blocks=Array.from({length:4},(_,b)=>units.slice(b*6,b*6+6));
 shell(`<div class="dashboard"><section class="learning-column"><div class="welcome-card"><div class="welcome-copy"><span class="pill light">${done()?'SIGUE DONDE LO DEJASTE':'TU PRIMER PASO'} · A1</span><h2>${done()?'Un paso más.<br>Un mundo más grande.':'Tu inglés<br>empieza aquí.'}</h2><p>${done()?esc(next.goal):'Aprende con pequeñas lecciones.<br>Úsalo en conversaciones de verdad.'}</p><button class="btn primary" data-action="lesson" data-unit="${next.id}" data-index="${idx}">${icon('play')}${done()?'Continuar mi lección':'Empezar a aprender'}</button><span class="tiny">${icon('clock')} 10–15 min · Unidad ${next.id}: ${esc(next.title)}</span></div><img class="welcome-image" src="assets/hello-robot.webp" alt="Personaje naranja con auriculares, un libro y un lápiz" width="1536" height="1024"></div><div class="quick-grid"><button class="quick-card" data-action="nav" data-to="lab"><span class="quick-icon orange">${icon('mic')}</span><span><b>¡Dilo en voz alta!</b><small>Escucha, habla y compara</small></span>${icon('chevron')}</button><button class="quick-card" data-action="nav" data-to="review"><span class="quick-icon blue">${icon('repeat')}</span><span><b>Que no se te olvide</b><small>Un repaso para hoy</small></span>${icon('chevron')}</button></div><div class="section-heading"><div><h2>Tu ruta A1</h2><p>24 unidades · 72 lecciones · todas disponibles</p></div><span class="pill blue">${done()} / 72</span></div>${blocks.map((us,b)=>`<section class="course-block"><div class="block-heading"><span class="block-number">0${b+1}</span><div><span class="eyebrow">ETAPA ${b+1}</span><h3>${blockNames[b]}</h3></div><span class="block-count">${us.reduce((a,u)=>a+uDone(u.id),0)} / 18 lecciones</span></div><div class="unit-grid">${us.map(u=>`<button class="unit-card ${u.id===next.id?'next':''} ${uDone(u.id)===3?'complete':''}" data-action="unit" data-unit="${u.id}"><span class="unit-top"><span class="unit-emoji hue${b}" aria-hidden="true">${u.icon}</span><span class="unit-index">${String(u.id).padStart(2,'0')}</span></span><span class="unit-english">${esc(u.en)}</span><h4>${esc(u.title)}</h4><span class="unit-bottom"><span class="lesson-dots">${[0,1,2].map(i=>`<i class="${state.completed[`${u.id}_${i}`]?'filled':''}"></i>`).join('')}</span><span>${uDone(u.id)===3?'Completada':`${uDone(u.id)}/3 lecciones`}</span>${icon(uDone(u.id)===3?'check':'chevron')}</span></button>`).join('')}</div><button class="checkpoint" data-action="exam" data-block="${b}"><span class="medallion">${icon('star')}</span><span><b>Comprueba tu avance</b><small>Repaso de las unidades ${b*6+1}–${b*6+6} · 12 preguntas</small></span><span class="btn-label">Hacer prueba</span></button></section>`).join('')}<div class="final-banner"><span>🏆</span><div><h3>¿Listo para tu desafío A1?</h3><p>48 preguntas de todo el curso, con resultados por unidad.</p></div><button class="btn primary" data-action="exam" data-block="all">Examen final</button></div></section><aside class="right-rail"><section class="panel daily"><div class="section-heading"><h3>Tu pequeño gran hábito</h3>${icon('flame')}</div><div class="goal-number">${Math.min(today,state.goal)}<small> / ${state.goal}</small></div><p>actividades de hoy</p>${percentBar(Math.min(100,Math.round(today/state.goal*100)))}<div class="week">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=d.toLocaleDateString('en-CA');return`<div><span>${['D','L','M','X','J','V','S'][d.getDay()]}</span><i class="${state.activity[key]?'yes':''}">${state.activity[key]?'✓':d.getDate()}</i></div>`;}).join('')}</div><p class="tiny">${today>=state.goal?'¡Objetivo de hoy conseguido!':'Un poco hoy vale más que todo algún día.'}</p></section><section class="panel progress-panel"><span class="eyebrow">TU VIAJE</span><h3>De cero a tus<br>primeras conversaciones</h3><div class="progress-donut" style="--pct:${pct}%"><b>${pct}<small>%</small></b></div><p>${done()} de 72 lecciones completadas</p><a href="#progress" class="text-link">Ver mi progreso</a></section><section class="tip-card"><span>💡</span><h3>Recuerda antes de mirar</h3><p>Intenta responder de memoria. Después, comprueba y aprende del error.</p><a href="#library/method">Así funciona el curso</a></section><section class="scene-card"><img src="assets/town-vocabulary.webp" alt="Una calle con un café, un bus, árboles y personas" width="1536" height="1024"><div><span class="eyebrow">APRENDE MIRANDO</span><h3>Una ciudad, muchas palabras</h3><button class="text-link" data-action="nav" data-to="vocab/scene">Explorar la escena</button></div></section></aside></div>`,'Hello, '+esc(state.name||'¡qué bueno verte!'));}
function ruleHTML(r){return`<section class="rule"><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p><div class="pattern">${esc(r.pattern)}</div><div class="examples">${r.examples.map(e=>`<div><span lang="en">${esc(e)}</span>${sound(e,true)}</div>`).join('')}</div><p class="rule-tip"><b>Recuerda:</b> ${esc(r.tip)}</p></section>`;}
function unitHTML(u,full=false){return`<div class="unit-detail-head"><span class="large-emoji">${u.icon}</span><div><p class="eyebrow">UNIDAD ${u.id} · ${esc(u.en)}</p><h2>${esc(u.title)}</h2><p>${esc(u.goal)}</p></div></div><div class="lesson-list">${u.rules.map((r,i)=>`<button data-action="lesson" data-unit="${u.id}" data-index="${i}" class="lesson-row"><span class="lesson-circle ${state.completed[`${u.id}_${i}`]?'finished':''}">${state.completed[`${u.id}_${i}`]?icon('check'):i+1}</span><span><b>${esc(r.title)}</b><small>${['Comprende y reconoce','Construye tus frases','Llévalo a una situación real'][i]} · ${state.completed[`${u.id}_${i}`]?`Mejor resultado: ${state.completed[`${u.id}_${i}`].score}%`:'7 actividades'}</small></span>${icon('play')}</button>`).join('')}</div><div class="detail-grid"><div><h2 class="section-title">Tu explicación, paso a paso</h2>${u.rules.map(ruleHTML).join('')}<section class="panel reading"><div class="section-heading"><h3>Una lectura para ti</h3>${sound(u.story)}</div><p class="reading-text" lang="en">${esc(u.story)}</p><details><summary>Comprueba tu comprensión</summary>${u.reading.map(r=>`<p><b>${esc(r.prompt)}</b><br>${esc(r.answer)}. ${esc(r.why)}</p>`).join('')}</details></section><section class="panel"><h3>Ahora escribe tú</h3><p>${esc(u.writing)}</p><label class="sr-only" for="writing-${u.id}">Tu respuesta escrita</label><textarea id="writing-${u.id}" data-writing="${u.id}" placeholder="Write your ideas here…" rows="5" maxlength="2000" lang="en">${esc(state.writing[u.id]||'')}</textarea><div class="writing-footer"><span id="word-count">${wordCount(state.writing[u.id]||'')} palabras · ${store.user?'guardado en tu cuenta al sincronizar':'guardado local'}</span><button class="btn soft" data-action="writing-check" data-unit="${u.id}">Revisar mi texto</button></div><div id="writing-feedback"></div><details><summary>Ver un modelo y lista de revisión</summary><p lang="en">${esc(u.model)}</p><ul><li>¿Respondí todos los puntos?</li><li>¿Incluí sujeto y verbo?</li><li>¿Revisé I, nombres y puntuación?</li><li>¿Puedo leerlo en voz alta y explicar qué significa?</li></ul><p class="tiny">La escritura libre se revisa con el modelo y esta lista. No se califica automáticamente su gramática.</p></details></section></div><aside><section class="panel"><h3>Las palabras de esta unidad</h3><div class="word-list">${u.vocab.map(v=>`<div><span class="word-emoji">${v.icon}</span><span><b lang="en">${esc(v.en)}</b><small>${esc(v.es)}</small></span>${sound(v.en,true)}</div>`).join('')}</div></section><section class="panel dialogue"><h3>Una conversación real</h3><p class="tiny">Escucha cada turno y luego practica tu parte.</p>${u.dialogue.map(([a,t],i)=>`<div class="dialogue-line ${a==='You'?'you':''}"><span>${a==='You'?'Tu turno':esc(a)}</span><p lang="en">${esc(t)}</p>${sound(t,true)}</div>`).join('')}<button class="btn primary full" data-action="speak-unit" data-unit="${u.id}">${icon('mic')} Practicar en voz alta</button></section></aside></div>`;}
function renderUnit(id){const u=units[id-1];if(!u)return nav('route');shell(`<a class="back-link" href="#route">Volver a mi ruta</a>${unitHTML(u)}`,'Unidad '+id,'APRENDE · PRACTICA · ÚSALO');}
function normalize(s){return String(s||'').toLowerCase().replace(/[’‘]/g,"'").replace(/\bi'm\b/g,'i am').replace(/\byou're\b/g,'you are').replace(/\bwe're\b/g,'we are').replace(/\bthey're\b/g,'they are').replace(/\bit's\b/g,'it is').replace(/\bshe's\b/g,'she is').replace(/\bhe's\b/g,'he is').replace(/\bthat's\b/g,'that is').replace(/\bthere's\b/g,'there is').replace(/\bwhat's\b/g,'what is').replace(/\bdon't\b/g,'do not').replace(/\bdoesn't\b/g,'does not').replace(/\bdidn't\b/g,'did not').replace(/\bisn't\b/g,'is not').replace(/\baren't\b/g,'are not').replace(/\bwasn't\b/g,'was not').replace(/\bweren't\b/g,'were not').replace(/\bcan't\b/g,'cannot').replace(/\bcan not\b/g,'cannot').replace(/\bhaven't\b/g,'have not').replace(/\bhasn't\b/g,'has not').replace(/\b(i|you|we|they)'ve\b/g,'$1 have').replace(/\b(i|you|he|she|it|we|they)'ll\b/g,'$1 will').replace(/\bwon't\b/g,'will not').replace(/\bwouldn't\b/g,'would not').replace(/\bcouldn't\b/g,'could not').replace(/\bshouldn't\b/g,'should not').replace(/\bi'd\b/g,'i would').replace(/\blet's\b/g,'let us').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim();}
function wordCount(t){return t.trim()?t.trim().split(/\s+/).length:0;}
function shuffle(a){return [...a].sort(()=>Math.random()-.5);}
function qMC(q,id,unit){return{...q,type:'choice',id,unit,options:shuffle(q.options)};}
function vocabQ(v,id,unit){const wrong=vocab.filter(x=>x.es!==v.es&&x.en!==v.en);return{type:'choice',id,unit,prompt:`¿Qué significa “${v.en}”?`,answer:v.es,options:shuffle([v.es,...shuffle([...new Set(wrong.map(x=>x.es))]).slice(0,2)]),why:`${v.en} significa ${v.es}.`,illustration:v.icon};}
function gapQ(text,id,unit){const tokens=text.split(' ');let pos=tokens.findIndex(t=>/^(am|is|are|was|were|have|has|can|to|at|in|on|from|do|does|not|the|a|an|some|any|going|like|likes|my|your|her|his|with|for|than)$/i.test(t));if(pos<0)pos=Math.min(1,tokens.length-1);const answer=tokens[pos].replace(/[.,!?]/g,'');tokens[pos]='_____';return{type:'fill',id,unit,prompt:'Completa la palabra que falta.',sentence:tokens.join(' '),answer,why:`La frase completa es: ${text}`};}
function orderQ(text,id,unit){const answer=text.replace(/[.!?]$/,'');return{type:'order',id,unit,prompt:'Ordena las palabras para construir la frase.',answer,words:shuffle(answer.split(' ')).map((t,i)=>({t,id:i})),why:`El orden correcto es: ${text}`};}
function buildLesson(u,i){const q=u.questions.slice(i*2,i*2+2).map((x,j)=>qMC(x,`u${u.id}q${i*2+j}`,u.id));if(i===0){q.push(vocabQ(u.vocab[0],`u${u.id}v0q`,u.id),vocabQ(u.vocab[1],`u${u.id}v1q`,u.id),gapQ(u.rules[0].examples[0],`u${u.id}g0`,u.id),orderQ(u.rules[0].examples[1],`u${u.id}o0`,u.id),{type:'dictation',prompt:'Escucha y escribe la frase.',answer:u.rules[0].examples[2],why:'Compara palabra por palabra. También se aceptan las contracciones equivalentes.',id:`u${u.id}d0`,unit:u.id});}else if(i===1){q.push(vocabQ(u.vocab[4],`u${u.id}v4q`,u.id),vocabQ(u.vocab[5],`u${u.id}v5q`,u.id),gapQ(u.rules[1].examples[0],`u${u.id}g1`,u.id),orderQ(u.rules[1].examples[1],`u${u.id}o1`,u.id),{type:'dictation',prompt:'Escucha y escribe la frase.',answer:u.rules[1].examples[2],why:'Escucha otra vez y compara el texto.',id:`u${u.id}d1`,unit:u.id});}else{q.push(...u.reading.map((x,j)=>({...qMC(x,`u${u.id}r${j}`,u.id),passage:u.story})),{...vocabQ(u.vocab[10],`u${u.id}v10q`,u.id)},orderQ(u.rules[2].examples[0],`u${u.id}o2`,u.id),{type:'dictation',prompt:'Escucha una frase de la conversación y escríbela.',answer:u.dialogue[1][1],why:'Puedes volver a escucharla despacio y practicar tu turno en Hablar.',id:`u${u.id}d2`,unit:u.id});}return q;}
function initLesson(id,i){const u=units[id-1];if(!u||i<0||i>2)return nav('route');if(!session||session.key!==`${id}_${i}`){session={key:`${id}_${i}`,kind:'lesson',unit:id,lesson:i,title:u.rules[i].title,questions:buildLesson(u,i),idx:0,correct:0,answers:[],phase:'learn',chosen:null,order:[],evaluated:false};}renderLesson();}
function renderLesson(){if(session.phase!=='learn')return renderQuiz();const u=units[session.unit-1];shell(`<div class="lesson-intro"><a href="#unit/${u.id}" class="back-link">Volver a la unidad</a><div class="lesson-label">${u.icon} UNIDAD ${u.id} · LECCIÓN ${session.lesson+1}/3</div><h2>${esc(session.title)}</h2><p>${esc(u.goal)}</p>${ruleHTML(u.rules[session.lesson])}${session.lesson===2?`<section class="panel"><h3>Antes de practicar, lee</h3><p class="reading-text" lang="en">${esc(u.story)}</p>${sound(u.story)}</section>`:''}<div class="learn-footer"><span>${icon('clock')} 7 actividades · sin límite de tiempo</span><button class="btn primary" data-action="begin-quiz">Vamos a practicar ${icon('play')}</button></div></div>`,'Pequeños pasos, grandes avances','TU LECCIÓN');}
function startExam(block){const us=block==='all'?units:units.slice(Number(block)*6,Number(block)*6+6);if(!us.length)return;const questions=shuffle(us.flatMap(u=>[qMC(u.questions[(u.id-1)%6],`u${u.id}q${(u.id-1)%6}`,u.id),{...qMC(u.reading[0],`u${u.id}r0`,u.id),passage:u.story}]));session={key:'exam-'+Date.now(),kind:'exam',block,title:block==='all'?'Desafío final A1':`Prueba de la etapa ${Number(block)+1}`,questions,idx:0,correct:0,answers:[],phase:'run',chosen:null,order:[],evaluated:false};location.hash='exam';current='exam';renderQuiz();}
function startErrors(){const qs=Object.values(state.errors).slice(0,20).map(q=>({...q,options:q.options?shuffle(q.options):undefined}));if(!qs.length)return toast('Todavía no hay errores pendientes. Puedes practicar una lección.');session={key:'review-'+Date.now(),kind:'review',title:'Aprende de tus errores',questions:qs,idx:0,correct:0,answers:[],phase:'run',chosen:null,order:[],evaluated:false};location.hash='practice';current='review';renderQuiz();}
function renderQuiz(){if(!session)return nav('route');if(session.phase==='done')return renderResults();const q=session.questions[session.idx],pct=Math.round(session.idx/session.questions.length*100);shell(`<div class="quiz-wrap"><div class="quiz-top"><button class="icon-btn" data-action="exit-quiz" aria-label="Salir de la práctica">${icon('close')}</button>${percentBar(pct)}<span>${session.idx+1} / ${session.questions.length}</span></div><p class="eyebrow">${esc(session.title)}</p><h2>${esc(q.prompt)}</h2>${q.passage?`<details class="passage" open><summary>Lee el texto</summary><p lang="en">${esc(q.passage)}</p></details>`:''}${q.illustration?`<div class="quiz-illustration" aria-hidden="true">${q.illustration}</div>`:''}${q.sentence?`<p class="gap-sentence" lang="en">${esc(q.sentence)}</p>`:''}${q.type==='dictation'?`<div class="audio-question"><button class="listen-orb" data-say="${esc(q.answer)}" aria-label="Escuchar frase">${icon('volume')}</button><button class="btn soft" data-say="${esc(q.answer)}" data-rate="0.65">Escuchar lento</button><details><summary>No puedo escuchar</summary><p>Lee la frase, ocúltala e intenta escribirla. Esta actividad será práctica de memoria visual.</p><p lang="en">${esc(q.answer)}</p></details></div>`:''}${q.type==='choice'?`<div class="choices">${q.options.map((o,i)=>`<button class="choice ${session.chosen===o?'selected':''} ${session.evaluated&&o===q.answer?'correct':''} ${session.evaluated&&session.chosen===o&&o!==q.answer?'incorrect':''}" data-action="choose" data-option="${i}" ${session.evaluated?'disabled':''}><span>${i+1}</span>${esc(o)}${session.evaluated&&o===q.answer?icon('check'):''}</button>`).join('')}</div>`:q.type==='order'?`<div class="order-answer" aria-label="Tu frase">${session.order.length?session.order.map(id=>`<button data-action="unorder" data-id="${id}" ${session.evaluated?'disabled':''}>${esc(q.words.find(w=>w.id===id).t)}</button>`).join(''):'<span>Toca las palabras para formar la frase</span>'}</div><div class="word-bank">${q.words.map(w=>`<button data-action="order" data-id="${w.id}" ${session.order.includes(w.id)||session.evaluated?'disabled':''}>${esc(w.t)}</button>`).join('')}</div>`:`<label class="input-label" for="answer-input">${q.type==='dictation'?'Escribe lo que escuchas':'Tu respuesta'}</label><input id="answer-input" class="answer-input" autocomplete="off" autocapitalize="off" spellcheck="false" lang="en" placeholder="Type your answer…" value="${esc(session.chosen||'')}" ${session.evaluated?'disabled':''}>`}${session.evaluated?`<div class="feedback ${session.lastCorrect?'success':'retry'}" role="status"><span>${session.lastCorrect?'✓':'💡'}</span><div><h3>${session.lastCorrect?'¡Bien hecho!':'Un error, una oportunidad'}</h3>${!session.lastCorrect?`<p><b>Respuesta:</b> <span lang="en">${esc(q.answer)}</span></p>`:''}<p>${esc(q.why)}</p></div></div>`:''}<div class="quiz-footer"><span>${session.evaluated?'No hay vidas que perder. Sigue practicando.':'Piensa primero. Comprueba después.'}</span><button class="btn primary" data-action="${session.evaluated?'next-question':'check-answer'}">${session.evaluated?(session.idx===session.questions.length-1?'Ver resultado':'Continuar'):'Comprobar'}</button></div></div>`,session.kind==='exam'?'Pon a prueba lo aprendido':'Tu práctica de hoy','PRÁCTICA ACTIVA');}
function checkAnswer(){if(!session||session.evaluated)return;const q=session.questions[session.idx];let answer=q.type==='order'?session.order.map(id=>q.words.find(w=>w.id===id).t).join(' '):q.type==='choice'?session.chosen:$('#answer-input')?.value;if(!answer?.trim())return toast('Escribe o selecciona una respuesta primero.');session.chosen=answer;session.lastCorrect=q.type==='choice'?answer===q.answer:normalize(answer)===normalize(q.answer);session.evaluated=true;if(session.lastCorrect){session.correct++;delete state.errors[q.id];}else state.errors[q.id]=q;session.answers.push({id:q.id,unit:q.unit,correct:session.lastCorrect,answer,expected:q.answer,prompt:q.prompt});activity();renderQuiz();}
function finishQuiz(){const score=Math.round(session.correct/session.questions.length*100);session.score=score;session.phase='done';if(session.kind==='lesson'){const prev=state.completed[session.key];if(score>=70){state.completed[session.key]={score:Math.max(prev?.score||0,score),date:day()};if(!prev)state.xp+=30;}session.earned=!prev&&score>=70?30:0;}else if(session.kind==='exam'){state.exam.unshift({id:crypto.randomUUID(),date:day(),score,block:session.block,results:session.answers});state.exam=state.exam.slice(0,12);session.earned=0;}else{state.xp+=session.correct*2;session.earned=session.correct*2;}save();renderResults();}
function renderResults(){const pass=session.score>=70;shell(`<div class="results"><div class="result-medal">${pass?'🌟':'🌱'}</div><p class="eyebrow">${esc(session.title)}</p><h2>${pass?'¡Mira cuánto has avanzado!':'Ya sabes qué practicar'}</h2><p>${session.kind==='lesson'?(pass?'Lección completada. Puedes continuar o volver a practicar.':'Necesitas 70% para completar la lección. Lee las explicaciones y vuelve a intentarlo.'):'Este resultado orienta tu repaso; no es una certificación oficial.'}</p><div class="result-stats"><div><b>${session.score}%</b><span>aciertos</span></div><div><b>${session.correct}/${session.questions.length}</b><span>respuestas correctas</span></div><div><b>+${session.earned||0}</b><span>XP</span></div></div><div class="button-row"><button class="btn primary" data-action="result-next">${session.kind==='lesson'&&pass?'Siguiente paso':'Volver a mi ruta'}</button><button class="btn soft" data-action="retry-quiz">Repetir práctica</button></div><h3>Lo que aprendiste</h3><div class="answer-summary">${session.answers.map(a=>`<div class="${a.correct?'ok':'wrong'}"><span>${a.correct?'✓':'↻'}</span><div><b>${esc(a.prompt)}</b><p>${a.correct?'Correcto':`Tu respuesta: ${esc(a.answer)}`} · <span lang="en">${esc(a.expected)}</span></p></div></div>`).join('')}</div>${session.kind==='exam'?`<p class="tiny">Comprueba también conversación y escritura con la lista «Puedo hacerlo» de Mi progreso. Este test no evalúa por sí solo todas las destrezas A1.</p>`:''}</div>`,'Cada intento cuenta','RESULTADO');}
function renderVocab(){const filtered=vocab.filter(v=>(!filterVocab||String(v.unit)===filterVocab)&&(!searchVocab||normalize(v.en+' '+v.es).includes(normalize(searchVocab))));shell(`<div class="tab-row"><button class="${tab==='words'?'active':''}" data-action="vocab-tab" data-tab="words">Mis palabras</button><button class="${tab==='scene'?'active':''}" data-action="vocab-tab" data-tab="scene">Aprende mirando</button></div>${tab==='scene'?`<div class="scene-study"><div class="scene-photo"><img src="assets/town-vocabulary.webp" alt="Escena ilustrada: un café a la izquierda, un bus azul al centro, un árbol y un perro a la derecha" width="1536" height="1024">${[['bus',49,56],['tree',87,22],['dog',71,74],['café',34,42],['bench',67,82],['bread',7,40]].map(([w,x,y],i)=>`<button class="hotspot" style="left:${x}%;top:${y}%" data-say="${w}" aria-label="Escuchar ${w}">${i+1}</button>`).join('')}</div><section class="panel"><span class="eyebrow">LOOK, LISTEN, SAY</span><h2>Welcome to the neighbourhood</h2><p>Toca un número, escucha la palabra y di una frase. Después, intenta nombrar los objetos sin mirar la lista.</p><div class="scene-words">${[['bus','bus'],['tree','árbol'],['dog','perro'],['café','cafetería'],['bench','banco para sentarse'],['bread','pan']].map(([en,es],i)=>`<button data-say="${en}"><b>${i+1}</b><span lang="en">${en}</span><small>${es}</small>${icon('volume')}</button>`).join('')}</div><div class="pattern">There is a blue bus.<br>There are people in the café.</div><button class="btn primary" data-action="speak-unit" data-unit="15">Practicar la ciudad</button></section></div>`:`<div class="search-row"><label class="search-box">${icon('search')}<input id="vocab-search" type="search" placeholder="Busca en inglés o español…" value="${esc(searchVocab)}" aria-label="Buscar vocabulario"></label><label><span class="sr-only">Filtrar por unidad</span><select id="vocab-filter"><option value="">Todas las unidades</option>${units.map(u=>`<option value="${u.id}" ${filterVocab===String(u.id)?'selected':''}>${u.id}. ${esc(u.title)}</option>`).join('')}<option value="0" ${filterVocab==='0'?'selected':''}>Palabras extra</option></select></label><button class="btn primary" data-action="start-flash">${icon('repeat')} Tarjetas</button></div><p class="muted" id="vocab-count">${filtered.length} entradas · escucha y añade al repaso</p><div class="vocab-grid" id="vocab-grid">${vocabCards(filtered)}</div>`}`,'Palabras que se quedan','ESCUCHA · RECUERDA · REPITE');}
function vocabCards(list){return list.length?list.map(v=>`<article class="vocab-card"><div class="vocab-pic" aria-hidden="true">${v.icon}</div><div><h3 lang="en">${esc(v.en)}</h3><p>${esc(v.es)}</p>${v.group?`<small class="vocab-group">${esc(v.group)}</small>`:''}</div><div class="vocab-actions">${sound(v.en,true)}<button class="sound ${state.vocab[v.key]?'saved':''}" data-action="save-word" data-key="${v.key}" aria-label="${state.vocab[v.key]?'Palabra añadida al repaso':'Añadir al repaso'}">${icon(state.vocab[v.key]?'check':'repeat')}</button></div></article>`).join(''):'<div class="empty-state"><h3>No encontramos esa palabra</h3><p>Prueba otro término o cambia el filtro de unidad.</p></div>';}
function saveWord(key){if(state.vocab[key])return toast('Esa palabra ya está en tu repaso.');state.vocab[key]={due:Date.now(),interval:0,reviews:0};save();toast('Añadida a tu repaso.');renderVocab();}
function startFlash(dueOnly=false){let cards=dueOnly?vocab.filter(v=>state.vocab[v.key]&&state.vocab[v.key].due<=Date.now()):vocab.filter(v=>!filterVocab||String(v.unit)===filterVocab);if(!cards.length)return toast('No hay tarjetas pendientes para hoy. Puedes añadir más palabras.');flash={cards:shuffle(cards).slice(0,20),idx:0,revealed:false};location.hash='cards';current='review';renderFlash();}
function renderFlash(){if(!flash)return nav('review');if(flash.idx>=flash.cards.length){shell(`<div class="empty-state"><span class="empty-emoji">🌟</span><h2>Repaso completado</h2><p>Las palabras volverán a aparecer según cuándo necesites recordarlas.</p><a href="#review" class="btn primary">Volver al repaso</a></div>`,'Lo que recuerdas, crece','TARJETAS');return;}const v=flash.cards[flash.idx];shell(`<div class="flash-wrap"><a href="#review" class="back-link">Volver al repaso</a><p class="eyebrow">TARJETA ${flash.idx+1} DE ${flash.cards.length}</p>${percentBar(Math.round(flash.idx/flash.cards.length*100))}<div class="flash-card"><span class="flash-emoji">${v.icon}</span><h2 lang="en">${esc(v.en)}</h2>${sound(v.en)}<p>${flash.revealed?esc(v.es):'¿Recuerdas qué significa?'}</p></div>${flash.revealed?`<p class="center muted">Sé sincero: esto decide cuándo volverás a practicarla.</p><div class="button-row center"><button class="btn soft" data-action="grade-flash" data-grade="again">Necesito repasarla</button><button class="btn primary" data-action="grade-flash" data-grade="good">La recordé</button></div>`:`<button class="btn primary full" data-action="reveal-flash">Mostrar significado</button>`}</div>`,'Entrena tu memoria','REPASO ESPACIADO');}
function renderReview(){const due=vocab.filter(v=>state.vocab[v.key]?.due<=Date.now()).length,n=Object.keys(state.errors).length;shell(`<div class="review-hero"><span>🧠</span><div><h2>Recordar también se entrena.</h2><p>Primero intenta responder. Después mira la solución. Repite en días distintos.</p></div></div><div class="lab-home-links"><a href="#lab">Sonidos y boca animada</a><a href="#lab/stories">Historias con apoyo</a><a href="#lab/method">Mi rutina de práctica</a></div><div class="three-cards"><section class="panel review-card"><span class="quick-icon orange">${icon('repeat')}</span><h3>Tus errores, resueltos</h3><strong>${n}</strong><p>Preguntas que necesitan otra oportunidad. Desaparecen al responder bien.</p><button class="btn primary" data-action="start-errors" ${!n?'disabled':''}>Repasar errores</button></section><section class="panel review-card"><span class="quick-icon blue">${icon('book')}</span><h3>Palabras para hoy</h3><strong>${due}</strong><p>Tarjetas pendientes. Si recuerdas una, volverá en 1, 3, 7 o 14 días.</p><button class="btn primary" data-action="due-flash" ${!due?'disabled':''}>Repasar tarjetas</button></section><section class="panel review-card"><span class="quick-icon green">${icon('star')}</span><h3>Una mezcla nueva</h3><strong>12</strong><p>Practica la etapa que prefieras y descubre qué necesitas reforzar.</p><select id="review-block" aria-label="Etapa para repasar">${blockNames.map((n,i)=>`<option value="${i}">${i+1}. ${n}</option>`).join('')}</select><button class="btn primary" data-action="review-exam">Empezar prueba</button></section></div><section class="panel"><h3>Un ritmo que puedes mantener</h3><div class="method-steps"><div><b>01</b><h4>Aprende</h4><p>Lee una explicación y observa sus ejemplos.</p></div><div><b>02</b><h4>Recupera</h4><p>Responde sin mirar. Escucha y produce tus propias frases.</p></div><div><b>03</b><h4>Vuelve</h4><p>Repasa mañana y unos días después, especialmente tus errores.</p></div></div><a class="text-link" href="#vocab">Añadir palabras a mis tarjetas</a></section>`,'Un poquito de repaso','PARA QUE SE QUEDE CONTIGO');}
function spokenNormalize(s){let n=normalize(s);for(const [num,word] of extra.numbers)n=n.replace(new RegExp('\\b'+num+'\\b','g'),word);return n;}
function compareSpeech(expected,heard){const a=spokenNormalize(expected).split(' ').filter(Boolean),b=spokenNormalize(heard).split(' ').filter(Boolean);if(!a.length||!b.length)return null;const d=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));for(let i=0;i<=a.length;i++)d[i][0]=i;for(let j=0;j<=b.length;j++)d[0][j]=j;for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));let i=a.length,j=b.length,matched=Array(a.length).fill(false);while(i>0&&j>0){if(d[i][j]===d[i-1][j-1]+(a[i-1]===b[j-1]?0:1)){matched[i-1]=a[i-1]===b[j-1];i--;j--;}else if(d[i][j]===d[i-1][j]+1)i--;else j--;}return{score:Math.max(0,Math.round((1-d[a.length][b.length]/Math.max(a.length,b.length))*100)),words:a,matched};}
function phrases(){return(voiceUnit?units.filter(u=>u.id===voiceUnit):units).flatMap(u=>[...u.rules.map(r=>r.examples[0]),...u.dialogue.filter(([s])=>s==='You').map(([,t])=>t)].map(text=>({text,unit:u.id,title:u.title})));}
function renderSpeak(){const all=phrases();voiceIndex=Math.min(voiceIndex,all.length-1);const p=all[voiceIndex];const available=!!(window.SpeechRecognition||window.webkitSpeechRecognition);shell(`<div class="speaking-layout"><section><div class="speech-toolbar"><label>Practicar<select id="speech-unit"><option value="0">Todas las unidades</option>${units.map(u=>`<option value="${u.id}" ${voiceUnit===u.id?'selected':''}>${u.id}. ${esc(u.title)}</option>`).join('')}</select></label><label>Voz del ejemplo<select id="speech-accent"><option value="en-US" ${state.accent==='en-US'?'selected':''}>Inglés estadounidense</option><option value="en-GB" ${state.accent==='en-GB'?'selected':''}>Inglés británico</option></select></label></div><div class="speech-card"><span class="pill blue">UNIDAD ${p.unit} · FRASE ${voiceIndex+1} / ${all.length}</span><h2 lang="en">${esc(p.text)}</h2><p>Escucha. Repite. Mira qué palabras se entendieron.</p><div class="button-row center">${sound(p.text)}<button class="btn soft" data-say="${esc(p.text)}" data-rate="0.65">${icon('clock')} Más despacio</button></div><div class="mic-area"><button class="mic-button ${recording?'listening':''}" data-action="record" ${!available?'disabled':''} aria-label="${recording?'Detener reconocimiento':'Activar micrófono y hablar'}">${icon(recording?'close':'mic')}</button><b>${recording?'Te escucho… toca para terminar':'Toca y habla en inglés'}</b><span>${available?'Permite el micrófono cuando el navegador lo solicite.':'Este navegador no tiene reconocimiento de voz compatible.'}</span></div><div id="speech-live" aria-live="polite"><p class="voice-message">${esc(voiceMsg)}</p>${transcript?`<div class="transcript"><span class="eyebrow">EL NAVEGADOR ENTENDIÓ</span><p lang="en">${esc(transcript)}</p></div>`:''}${speechResult?`<div class="speech-score"><strong>${speechResult.score}<small>%</small></strong><div><h3>Coincidencia de palabras</h3><p>${speechResult.score===100?'Se reconocieron todas las palabras esperadas.':speechResult.score>=70?'Se reconoció gran parte de la frase. Repite las palabras resaltadas.':'Escucha de nuevo y prueba con calma. También puede haber errores del reconocimiento.'}</p></div></div><div class="word-feedback">${speechResult.words.map((w,i)=>`<span class="${speechResult.matched[i]?'matched':'missing'}">${esc(w)}</span>`).join('')}</div>`:''}</div><div class="speech-navigation"><button class="btn ghost" data-action="prev-phrase" ${voiceIndex===0?'disabled':''}>Anterior</button><span>${esc(p.title)}</span><button class="btn primary" data-action="next-phrase">Otra frase</button></div></div><div class="notice speech-notice"><b>Qué mide este porcentaje</b><p>Compara la transcripción con la frase esperada, teniendo en cuenta palabras omitidas, sustituidas o añadidas. No mide con precisión tu acento, entonación ni pronunciación. Un error puede venir del micrófono o del navegador.</p></div></section><aside><section class="panel"><span class="quick-icon orange">${icon('headphones')}</span><h3>Hazlo en tres pasos</h3><ol class="speaking-tips"><li><b>Escucha sin leer</b><span>¿Qué palabras reconoces?</span></li><li><b>Repite con el ejemplo</b><span>Imita el ritmo en fragmentos cortos.</span></li><li><b>Di la frase a solas</b><span>Oculta el texto e inténtalo de memoria.</span></li></ol></section><section class="panel"><h3>Tu voz y tu privacidad</h3><p>El reconocimiento lo ofrece tu navegador y puede enviar audio a su proveedor. No requiere que pongas una API. Esta página no guarda grabaciones.</p><p>Se guardan la frase de práctica, fecha y puntuación. Con tu cuenta iniciada, estos resultados también se sincronizan. No se guarda tu grabación ni la transcripción completa.</p><a class="text-link" href="#library/privacy">Compatibilidad y ayuda</a></section><section class="tip-card"><h3>Sonidos que merecen práctica</h3><p>Vocales, consonantes finales, /b/ y /v/, ritmo y terminaciones.</p><a href="#library/sounds">Abrir el taller de sonidos</a></section></aside></div>`,'Tu voz también aprende','ESCUCHA · HABLA · COMPARA');}
function startRecording(){if(recording){recognition?.stop();return;}const C=window.SpeechRecognition||window.webkitSpeechRecognition;if(!C)return toast('Prueba un navegador compatible o utiliza el ejemplo de audio para practicar.');if(!window.isSecureContext){voiceMsg='El micrófono requiere HTTPS o localhost. Publica la carpeta en Netlify y abre su enlace seguro.';return renderSpeak();}stopAudio();transcript='';speechResult=null;voiceMsg='';const target=phrases()[voiceIndex];const r=new C();recognition=r;r.lang=state.accent;r.continuous=false;r.interimResults=true;r.maxAlternatives=1;r.onstart=()=>{recording=true;renderSpeak();};r.onresult=e=>{transcript=Array.from(e.results).map(x=>x[0].transcript).join(' ');if(Array.from(e.results).some(x=>x.isFinal)){speechResult=compareSpeech(target.text,transcript);if(speechResult){state.speech.unshift({id:crypto.randomUUID(),phrase:target.text,score:speechResult.score,date:day(),unit:target.unit});state.speech=state.speech.slice(0,100);activity();}}renderSpeak();};r.onerror=e=>{const messages={'not-allowed':'No se permitió el micrófono. Actívalo en los permisos del sitio y vuelve a intentarlo.','service-not-allowed':'El servicio de voz no está disponible en este navegador. Puedes escuchar y repetir sin puntuación.','no-speech':'No se detectó voz. Acerca el micrófono y vuelve a intentarlo.','audio-capture':'No se encontró un micrófono disponible. Revisa la conexión.','network':'No se pudo conectar al reconocimiento. Revisa tu internet o prueba otro navegador.','aborted':'La escucha se detuvo. Puedes volver a intentarlo.','language-not-supported':'El servicio no admite esta variante de inglés. Prueba la otra voz.'};voiceMsg=messages[e.error]||'No se pudo reconocer el audio. Inténtalo otra vez.';recording=false;renderSpeak();};r.onend=()=>{recording=false;if(!transcript&&!voiceMsg)voiceMsg='No se recibió una transcripción. Puedes intentarlo otra vez.';recognition=null;renderSpeak();};try{r.start();}catch{voiceMsg='No se pudo iniciar el micrófono. Revisa los permisos y utiliza el sitio publicado con HTTPS.';renderSpeak();}}
function renderLibrary(section=libraryTab){libraryTab=section;const tabs=[['guide','Guía de estudio'],['basics','Bases esenciales'],['sounds','Sonidos'],['resources','Recursos gratuitos'],['method','Cómo aprender'],['privacy','Voz y privacidad']];let html='';if(section==='guide')html=`<div class="library-hero"><div><span class="pill light">TU LIBRO DE CONSULTA</span><h2>Todo tu A1,<br>en un solo lugar.</h2><p>Consulta la gramática, vuelve a un ejemplo o imprime el material para estudiar en papel.</p><button class="btn primary" data-action="print-guide">${icon('download')} Abrir guía imprimible</button></div><img src="assets/hello-robot.webp" alt="Personaje del curso con un libro" width="1536" height="1024"></div><div class="grammar-index">${units.map(u=>`<a href="#unit/${u.id}"><span>${String(u.id).padStart(2,'0')}</span><div><h3>${esc(u.title)}</h3><p>${u.rules.map(r=>esc(r.title)).join(' · ')}</p></div>${icon('chevron')}</a>`).join('')}</div>`;
else if(section==='basics')html=`<section class="panel"><h2>El abecedario</h2><p>Escucha el nombre de cada letra. Los símbolos son una referencia de inglés británico; la voz seleccionada puede decir Z como zee en inglés estadounidense.</p><div class="alphabet-grid">${extra.alphabet.map(([c,ipa])=>`<button data-say="${c}" aria-label="Escuchar letra ${c}"><b>${c}</b><small>${ipa}</small>${icon('volume')}</button>`).join('')}</div></section><div class="detail-grid"><section class="panel"><h2>Números esenciales</h2><div class="reference-list">${extra.numbers.map(([n,t])=>`<div><b>${n}</b><span lang="en">${t}</span>${sound(t,true)}</div>`).join('')}</div><p><b>21–99:</b> une decena y unidad: twenty-one, forty-five, ninety-nine. <b>101:</b> one hundred and one (también one hundred one en EE. UU.).</p><div class="number-practice"><label for="number-input">Escribe un número del 0 al 1000</label><input id="number-input" type="number" min="0" max="1000" value="21"><button class="btn soft" data-action="number-say">Ver y escuchar</button><p id="number-output" lang="en"></p></div></section><div><section class="panel"><h2>Los meses</h2><div class="reference-list">${extra.months.map(([en,es])=>`<div><b lang="en">${en}</b><span>${es}</span>${sound(en,true)}</div>`).join('')}</div></section><section class="panel"><h2>Ordinales para fechas</h2><div class="reference-list">${extra.ordinals.map(([en,es])=>`<div><b lang="en">${en}</b><span>${es}</span>${sound(en,true)}</div>`).join('')}</div></section></div></div><section class="panel"><h2>Pronombres: quién hace, quién recibe y de quién es</h2><div class="table-scroll"><table><thead><tr><th>Sujeto</th><th>Objeto</th><th>Posesivo + nombre</th><th>Ejemplo</th></tr></thead><tbody>${[['I','me','my','I have my book. Help me.'],['you','you','your','You have your book. I help you.'],['he','him','his','He has his book. I help him.'],['she','her','her','She has her book. I help her.'],['it','it','its','It has its place. I like it.'],['we','us','our','We have our books. Help us.'],['they','them','their','They have their books. I help them.']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;
else if(section==='sounds')html=`<div class="notice"><b>Aprende a escuchar las diferencias</b><p>Repite sin forzar la voz. Estas explicaciones y audios son orientativos; el reconocimiento de voz no es una evaluación fonética profesional.</p></div><div class="sound-grid">${extra.pronunciation.map(([title,pair,text,a,b])=>`<section class="panel"><span class="pill blue">${esc(title)}</span><h3 lang="en">${esc(pair)}</h3><p>${esc(text)}</p><div class="button-row"><button class="btn soft" data-say="${esc(a)}">${icon('volume')} ${esc(a)}</button><button class="btn soft" data-say="${esc(b)}">${icon('volume')} ${esc(b)}</button></div></section>`).join('')}</div><section class="panel"><h3>Una sesión de cinco minutos</h3><ol><li>Escucha dos palabras sin mirar y distingue cuál oyes.</li><li>Mira el ejemplo y repítelo tres veces con calma.</li><li>Usa la palabra dentro de una frase.</li><li>Vuelve a probar mañana. Prioriza que se entienda tu mensaje.</li></ol></section>`;
else if(section==='resources')html=`<p class="lead">Recursos oficiales para complementar el curso. Se abren en otra página; sus materiales conservan sus propios derechos y condiciones.</p><div class="resources">${extra.resources.map(([name,title,desc,url,logo])=>`<a class="resource-card" href="${url}" target="_blank" rel="noopener noreferrer"><span class="resource-logo">${logo}</span><div><span class="eyebrow">${name}</span><h3>${title}</h3><p>${desc}</p><span class="text-link">Abrir recurso oficial ${icon('globe')}</span></div></a>`).join('')}</div><div class="notice">El contenido didáctico de Hello A1 es original. Los enlaces no implican afiliación con Cambridge, Oxford o British Council. No se incluyen copias de libros comerciales.</div>`;
else if(section==='method')html=`<div class="method-page"><h2>Aprender es poder usarlo.</h2><p class="lead">La ruta mezcla comprensión y producción. La repetición espaciada y la práctica de recuperación ayudan a recordar; no existe un método único que garantice ser el mejor para todas las personas.</p><div class="three-cards"><section class="panel"><h3>1. Comprende</h3><p>Lee una explicación, escucha ejemplos y relaciona palabras con imágenes. Empieza por el significado.</p></section><section class="panel"><h3>2. Produce</h3><p>Responde sin mirar, construye una frase, escribe un mensaje y habla en voz alta.</p></section><section class="panel"><h3>3. Recuerda</h3><p>Vuelve a los errores y a las tarjetas al día siguiente y en intervalos crecientes.</p></section></div><section class="panel"><h3>Tu sesión sugerida: 20 minutos</h3><ol><li><b>3 minutos:</b> recuerda palabras de ayer.</li><li><b>7 minutos:</b> aprende una idea y practica.</li><li><b>5 minutos:</b> escucha y habla.</li><li><b>5 minutos:</b> escribe algo sobre tu vida y revisa el modelo.</li></ol><p>Si tienes menos tiempo, haz una parte hoy y otra mañana. El ritmo y la repetición importan más que una racha perfecta.</p></section><section class="panel"><h3>Qué incluye y qué no promete</h3><p>24 unidades y 72 lecciones sobre comunicación cotidiana A1. Las unidades de pasado, planes y comparaciones introducen estructuras sencillas que después se amplían en A2. El MCER define capacidades comunicativas; no existe una lista universal cerrada de todos los temas o palabras de A1.</p><p>Los puntos y pruebas son orientativos. El curso no garantiza un nivel en un plazo fijo ni emite certificados oficiales. La escritura se revisa con modelos y criterios; el porcentaje oral mide coincidencia de palabras reconocidas.</p><p><a href="https://www.psychologicalscience.org/news/releases/which-study-strategies-make-the-grade.html" target="_blank" rel="noopener noreferrer">Fuente sobre práctica de recuperación y aprendizaje distribuido</a> · <a href="https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions" target="_blank" rel="noopener noreferrer">Descriptores MCER</a></p></section></div>`;
else if(section==='privacy')html=`<section class="panel"><h2>Tu progreso, tu cuenta</h2><p>Como invitado, tu avance se guarda en este navegador. Al acceder con Google, Firebase Authentication identifica tu cuenta y Cloud Firestore guarda tus lecciones, tarjetas, borradores, preferencias y resultados. Las reglas incluidas restringen la lectura y escritura a esa cuenta.</p><p>Google gestiona el acceso: la página no solicita ni guarda tu contraseña. Firebase puede proporcionar el nombre y correo de tu cuenta para mostrarte con quién has entrado. No copiamos el correo a los documentos de progreso.</p><p>La sesión de acceso se conserva durante esta sesión del navegador. Cierra sesión cuando termines en un equipo compartido. Puede quedar una copia local de tu progreso para recuperar cambios pendientes; borrar los datos de este sitio elimina esa copia.</p><h3>Conexión y sincronización</h3><p>El guardado ocurre al estudiar y al volver a la pestaña. Si falla, se muestra como pendiente: no se afirma que ya está en la nube. Puedes exportar una copia desde Mi progreso. Al editar el mismo borrador desde dos equipos, prevalece el último cambio guardado; usa un equipo a la vez para esa redacción.</p><h3>Tu voz</h3><p>El reconocimiento puede enviar audio al proveedor del navegador y requiere permiso. La página no guarda grabaciones ni la transcripción completa. Guarda la frase de práctica, fecha y puntuación; con sesión iniciada también se sincronizan estos resultados. El porcentaje compara palabras reconocidas, no evalúa fonemas ni acento.</p><h3>Gestionar tus datos</h3><p>En Mi progreso puedes exportar, importar o reiniciar tu progreso A1. Con sesión iniciada, el reinicio se aplica a esa cuenta en la nube. Esto no elimina tu cuenta de Google. El modo invitado tiene un progreso independiente que solo se añade a tu cuenta si tú lo eliges.</p><p>No se han añadido analítica publicitaria, pagos ni tutor generativo. Los recursos externos tienen sus propias condiciones. <a href="https://policies.google.com/privacy" target="_blank" rel="noopener noreferrer">Privacidad de Google</a> · <a href="https://firebase.google.com/support/privacy" target="_blank" rel="noopener noreferrer">Privacidad de Firebase</a></p></section>`;
 shell(`<div class="tab-row wrap">${tabs.map(([id,label])=>`<a href="#library/${id}" class="${id===section?'active':''}">${label}</a>`).join('')}</div>${html}`,'Tu biblioteca A1','CONSULTA A TU RITMO');}
function renderProgress(){const total=done(),n=state.speech.length;const checks=state.checks||[];shell(`<div class="progress-overview"><div><span>Lecciones completadas</span><b>${total}<small> / 72</small></b>${percentBar(Math.round(total/72*100))}</div><div><span>Unidades completadas</span><b>${units.filter(u=>uDone(u.id)===3).length}<small> / 24</small></b></div><div><span>Días de práctica</span><b>${Object.keys(state.activity).length}</b></div><div><span>Intentos de voz guardados</span><b>${n}</b></div></div><div class="detail-grid"><section><div class="panel"><h2>Puedo hacerlo</h2><p>Marca una capacidad cuando puedas demostrarla sin copiar un modelo. Es tu autoevaluación.</p><div class="checklist">${extra.checklist.map((t,i)=>`<label><input type="checkbox" data-check="${i}" ${checks.includes(i)?'checked':''}><span>${esc(t)}</span></label>`).join('')}</div></div><div class="panel"><h2>Tu mapa de avances</h2><div class="progress-units">${units.map(u=>`<a href="#unit/${u.id}"><span>${u.icon}</span><div><b>${u.id}. ${esc(u.title)}</b>${percentBar(Math.round(uDone(u.id)/3*100))}</div><span>${uDone(u.id)}/3</span></a>`).join('')}</div></div><div class="panel"><h2>Últimas pruebas</h2>${state.exam.length?state.exam.map(e=>`<div class="history-row"><span><b>${e.block==='all'?'Examen final A1':`Etapa ${Number(e.block)+1}`}</b><small>${esc(e.date)}</small></span><strong>${e.score}%</strong></div>`).join(''):'<p>Tu primera prueba aparecerá aquí. Puedes hacer las pruebas de etapa desde Mi ruta.</p>'}</div></section><aside><section class="panel"><h3>A tu manera</h3><label class="field-label" for="profile-name">¿Cómo te llamamos?</label><input id="profile-name" maxlength="30" placeholder="Tu nombre" value="${esc(state.name)}"><label class="field-label" for="daily-goal">Objetivo diario</label><select id="daily-goal">${[5,10,15,20].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} actividades</option>`).join('')}</select><button class="btn primary full" data-action="save-settings">Guardar preferencias</button></section><section class="panel"><h3>Conserva tu progreso</h3><a class="text-link" href="#account">${store.user?'Ver mi cuenta y sincronización':'Guardar con mi cuenta de Google'}</a><p>${store.user?'El progreso se guarda en tu cuenta cuando hay conexión. Puedes conservar además una copia descargada.':'Estás como invitado: el progreso se guarda en este navegador. Entra con Google para guardarlo en tu cuenta.'}</p><button class="btn soft full" data-action="export">${icon('download')} Exportar progreso</button><label class="btn ghost full import-button">Importar copia<input type="file" id="import-progress" accept="application/json,.json"></label><button class="text-danger" data-action="reset">Borrar mi progreso</button></section><section class="panel"><h3>Últimas frases</h3>${state.speech.slice(0,6).map(s=>`<div class="voice-history"><p lang="en">${esc(s.phrase)}</p><span>${s.score}% coincidencia · ${esc(s.date)}</span></div>`).join('')||'<p>Cuando practiques con el micrófono verás tus resultados aquí.</p>'}<p class="tiny">Las puntuaciones de voz no certifican pronunciación.</p></section></aside></div>`,'Mira todo lo que avanzas','TU PROGRESO');}
function numberWords(n){const basic=Object.fromEntries(extra.numbers);if(basic[n])return basic[n];if(n<100)return basic[Math.floor(n/10)*10]+'-'+basic[n%10];return basic[Math.floor(n/100)]+' hundred'+(n%100?' and '+numberWords(n%100):'');}
function renderPrint(){document.body.classList.add('print-mode');$('#app').innerHTML=`<main class="print-book"><div class="print-toolbar"><a href="#library" class="btn soft">Volver a la página</a><button class="btn primary" data-action="print">Imprimir / guardar como PDF</button></div><header class="book-cover"><span class="brand-mark">h!</span><p>HELLO A1 · INGLÉS DESDE CERO</p><h1>Tu primera<br>conversación<br>empieza aquí.</h1><p>Guía de estudio para hispanohablantes</p><p>24 unidades · gramática · vocabulario · lecturas · diálogos · escritura</p><img src="assets/hello-robot.webp" alt="Personaje con un libro" width="600"><p>Material original. Referencia orientativa A1; no es una certificación oficial. La pronunciación y las actividades interactivas están en la web.</p></header><section><h2>Cómo usar esta guía</h2><p>Estudia una explicación, escucha los ejemplos en la web, responde sin mirar y vuelve a practicar otro día. Después escribe tus propias frases y léelas en voz alta. Las unidades 20–22 introducen pasado y planes sencillos que luego se amplían en A2.</p><ol>${units.map(u=>`<li>${esc(u.title)} — ${esc(u.goal)}</li>`).join('')}</ol></section>${units.map(u=>`<article class="print-unit"><h2>${u.id}. ${esc(u.title)}</h2><p>${esc(u.goal)}</p>${u.rules.map(r=>`<h3>${esc(r.title)}</h3><p>${esc(r.text)}</p><p><b>${esc(r.pattern)}</b></p><ul>${r.examples.map(e=>`<li lang="en">${esc(e)}</li>`).join('')}</ul><p><i>${esc(r.tip)}</i></p>`).join('')}<h3>Vocabulario</h3><div class="print-vocab">${u.vocab.map(v=>`<span><b>${esc(v.en)}</b> — ${esc(v.es)}</span>`).join('')}</div><h3>Lectura</h3><p lang="en">${esc(u.story)}</p>${u.reading.map(r=>`<p>${esc(r.prompt)} ____________________</p>`).join('')}<h3>Conversación</h3>${u.dialogue.map(([a,t])=>`<p><b>${esc(a)}:</b> <span lang="en">${esc(t)}</span></p>`).join('')}<h3>Practica</h3>${u.questions.map((q,i)=>`<p>${i+1}. ${esc(q.prompt)}<br>${shuffle(q.options).map(o=>esc(o)).join(' / ')}</p>`).join('')}<h3>Escritura</h3><p>${esc(u.writing)}</p><div class="writing-lines"></div></article>`).join('')}<section class="print-unit"><h2>Soluciones y modelos</h2>${units.map(u=>`<h3>Unidad ${u.id}</h3><p>${u.questions.map((q,i)=>`${i+1}. ${esc(q.answer)} (${esc(q.why)})`).join(' · ')}</p><p><b>Lectura:</b> ${u.reading.map(r=>esc(r.answer)).join(' · ')}</p><p><b>Modelo de escritura:</b> ${esc(u.model)}</p>`).join('')}</section><section class="print-unit"><h2>Recursos oficiales y método</h2>${extra.resources.map(r=>`<p><b>${r[0]} — ${r[1]}</b><br>${r[3]}</p>`).join('')}<p>Material creado para Hello A1. Las ilustraciones originales se generaron para este curso. Los recursos externos pertenecen a sus titulares.</p></section></main>`;}
function routeChanged(){stopLab();stopAudio();document.body.classList.remove('print-mode');const [r,id,index]=(location.hash.slice(1)||'home').split('/');current=r;window.scrollTo(0,0);if(r==='route')renderRoute();else if(r==='unit')renderUnit(Number(id));else if(r==='lesson')initLesson(Number(id),Number(index)||0);else if(r==='vocab'){tab=id==='scene'?'scene':'words';renderVocab();}else if(r==='speak')renderSpeak();else if(r==='review')renderReview();else if(r==='cards')renderFlash();else if(r==='library')renderLibrary(id||'guide');else if(r==='progress')renderProgress();else if(r==='lab'){stopAudio();shell(renderLab(store,window.COURSE),'Escucha, observa y practica','LABORATORIO DE INGLÉS');}else if(r==='home')renderHome();else if(r==='account')renderAccount();else if(r==='print')renderPrint();else if(r==='exam'||r==='practice'){if(session)renderQuiz();else nav('route');}else nav('route');}
function resetVoice(){stopAudio();transcript='';speechResult=null;voiceMsg='';}
document.addEventListener('click',e=>{const say=e.target.closest('[data-say]');if(say){speak(say.dataset.say,Number(say.dataset.rate)||.85);return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;switch(a){case'nav':nav(b.dataset.to);break;case'google-login':void store.login();break;case'google-logout':void store.logout();break;case'sync-account':void store.sync();break;case'import-guest':if(confirm('¿Añadir a tu cuenta el progreso de invitado de este navegador? Tus lecciones ya guardadas se conservarán.'))store.importGuest();break;case'unit':nav('unit/'+b.dataset.unit);break;case'lesson':session=null;nav(`lesson/${b.dataset.unit}/${b.dataset.index}`);break;case'begin-quiz':session.phase='run';renderQuiz();break;case'choose':session.chosen=session.questions[session.idx].options[Number(b.dataset.option)];renderQuiz();break;case'order':session.order.push(Number(b.dataset.id));renderQuiz();break;case'unorder':session.order=session.order.filter(n=>n!==Number(b.dataset.id));renderQuiz();break;case'check-answer':checkAnswer();break;case'next-question':if(!session.evaluated)break;if(session.idx===session.questions.length-1)finishQuiz();else{session.idx++;session.chosen=null;session.order=[];session.evaluated=false;renderQuiz();}break;case'exit-quiz':if(confirm('¿Salir de esta práctica? Las respuestas ya realizadas se conservarán para tu repaso.')){const u=session?.unit;session=null;nav(u?'unit/'+u:'route');}break;case'result-next':{if(session.kind==='lesson'&&session.score>=70){const u=session.unit,i=session.lesson;session=null;if(i<2)nav(`lesson/${u}/${i+1}`);else if(u<24)nav(`unit/${u+1}`);else nav('progress');}else{session=null;nav('route');}break;}case'retry-quiz':session.idx=0;session.correct=0;session.answers=[];session.chosen=null;session.order=[];session.evaluated=false;session.phase=session.kind==='lesson'?'learn':'run';if(session.phase==='learn')renderLesson();else renderQuiz();break;case'exam':startExam(b.dataset.block);break;case'review-exam':startExam($('#review-block').value);break;case'start-errors':startErrors();break;case'vocab-tab':nav(b.dataset.tab==='scene'?'vocab/scene':'vocab');break;case'save-word':saveWord(b.dataset.key);break;case'start-flash':startFlash();break;case'due-flash':startFlash(true);break;case'reveal-flash':flash.revealed=true;renderFlash();break;case'grade-flash':{if(!flash?.revealed)break;const v=flash.cards[flash.idx];const prev=state.vocab[v.key]||{reviews:0,interval:0};const interval=b.dataset.grade==='good'?(prev.interval===0?1:prev.interval===1?3:prev.interval===3?7:14):0;state.vocab[v.key]={reviews:prev.reviews+1,interval,due:Date.now()+(interval?interval*86400000:10*60000)};activity();flash.idx++;flash.revealed=false;renderFlash();break;}case'speak-unit':voiceUnit=Number(b.dataset.unit);voiceIndex=0;resetVoice();nav('speak');break;case'record':startRecording();break;case'next-phrase':resetVoice();voiceIndex=(voiceIndex+1)%phrases().length;renderSpeak();break;case'prev-phrase':resetVoice();voiceIndex=Math.max(0,voiceIndex-1);renderSpeak();break;case'print-guide':nav('print');break;case'print':window.print();break;case'number-say':{const n=Number($('#number-input').value);if(!Number.isInteger(n)||n<0||n>1000)return toast('Escribe un número entero entre 0 y 1000.');const w=numberWords(n);$('#number-output').textContent=w;speak(w);break;}case'writing-check':{const u=units[Number(b.dataset.unit)-1],v=$(`#writing-${u.id}`).value;const n=wordCount(v);if(!n)return toast('Escribe tu texto primero.');const notes=[n<3?'Añade una frase completa.':`Has escrito ${n} palabras.`,/\bi\b/.test(v)?'Revisa la mayúscula de I.':'Comprueba que I y los nombres propios tengan mayúscula.',/[.!?]$/.test(v.trim())?'Hay puntuación final.':'Añade puntuación al final.'];$('#writing-feedback').innerHTML=`<div class="notice"><b>Revisión de formato</b><ul>${notes.map(n=>`<li>${n}</li>`).join('')}</ul><p>No se ha comprobado automáticamente la corrección gramatical. Compara ahora con el modelo y la lista de revisión.</p></div>`;activity();break;}case'save-settings':state.name=$('#profile-name').value.trim().slice(0,30);state.goal=Number($('#daily-goal').value);save();renderProgress();toast('Preferencias guardadas.');break;case'export':downloadJSON();break;case'reset':if(confirm(store.user?'¿Borrar tu progreso A1 de esta cuenta? Se aplicará también en tus otros dispositivos. Puedes exportar una copia antes.':'¿Borrar el progreso A1 de invitado en este navegador? Puedes exportar una copia antes.')){void store.replace(defaults()).then(ok=>{if(ok){state=hydrateProgress(store.getState());session=null;nav('progress');toast('Progreso A1 reiniciado.');}else toast('No se pudo completar el reinicio. Tu progreso se conserva.');});}break;}});
document.addEventListener('input',e=>{if(e.target.matches('[data-writing]')){state.writing[e.target.dataset.writing]=e.target.value.slice(0,2000);save();const c=$('#word-count');if(c)c.textContent=wordCount(e.target.value)+' palabras · '+(store.user?'pendiente de sincronización':'guardado local');}if(e.target.id==='answer-input'&&session)session.chosen=e.target.value;if(e.target.id==='vocab-search'){searchVocab=e.target.value;const list=vocab.filter(v=>(!filterVocab||String(v.unit)===filterVocab)&&normalize(v.en+' '+v.es).includes(normalize(searchVocab)));$('#vocab-grid').innerHTML=vocabCards(list);$('#vocab-count').textContent=`${list.length} entradas · escucha y añade al repaso`;}});
document.addEventListener('change',e=>{if(e.target.id==='vocab-filter'){filterVocab=e.target.value;renderVocab();}if(e.target.id==='speech-unit'){voiceUnit=Number(e.target.value);voiceIndex=0;resetVoice();renderSpeak();}if(e.target.id==='speech-accent'){resetVoice();state.accent=e.target.value;save();renderSpeak();}if(e.target.matches('[data-check]')){const i=Number(e.target.dataset.check);state.checks=e.target.checked?[...new Set([...state.checks,i])]:state.checks.filter(n=>n!==i);save();}if(e.target.id==='import-progress')importProgress(e.target.files[0]);});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='answer-input'){e.preventDefault();checkAnswer();}});
function downloadJSON(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Hello-A1-progreso-${day()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importProgress(file){if(!file)return;if(file.size>2000000)return toast('La copia es demasiado grande. Selecciona una exportación de Hello A1.');try{const s=JSON.parse(await file.text());if(s.version!==1||!s.completed||!s.activity||!s.vocab||!Array.isArray(s.exam)||!Array.isArray(s.speech))throw Error();const n=defaults();n.name=String(s.name||'').slice(0,30);n.goal=[5,10,15,20].includes(s.goal)?s.goal:10;n.accent=['en-US','en-GB'].includes(s.accent)?s.accent:'en-US';n.xp=Number.isFinite(s.xp)?Math.max(0,Math.min(1000000,s.xp)):0;for(const[k,v]of Object.entries(s.completed)){if(/^([1-9]|1\d|2[0-4])_[012]$/.test(k)&&Number.isFinite(v.score)&&v.score>=70&&v.score<=100)n.completed[k]={score:v.score,date:String(v.date).slice(0,10)};}for(const[k,v]of Object.entries(s.activity)){if(/^\d{4}-\d{2}-\d{2}$/.test(k)&&Number.isFinite(v))n.activity[k]=Math.max(0,Math.min(10000,v));}for(const[k,v]of Object.entries(s.vocab)){if(vocab.some(w=>w.key===k)&&Number.isFinite(v.due))n.vocab[k]={due:v.due,interval:[0,1,3,7,14].includes(v.interval)?v.interval:0,reviews:Math.max(0,Number(v.reviews)||0)};}for(const[k,v]of Object.entries(s.writing||{})){if(units.some(u=>String(u.id)===k)&&typeof v==='string')n.writing[k]=v.slice(0,2000);}n.checks=Array.isArray(s.checks)?s.checks.filter(i=>Number.isInteger(i)&&i>=0&&i<extra.checklist.length):[];n.speech=s.speech.filter(x=>typeof x.phrase==='string'&&Number.isFinite(x.score)&&x.score>=0&&x.score<=100).slice(0,100).map(x=>({phrase:x.phrase.slice(0,300),score:x.score,date:String(x.date).slice(0,10),unit:Number(x.unit)||1}));n.exam=s.exam.filter(x=>Number.isFinite(x.score)&&x.score>=0&&x.score<=100&&(x.block==='all'||['0','1','2','3'].includes(String(x.block)))).slice(0,12).map(x=>({score:x.score,block:x.block,date:String(x.date).slice(0,10),results:[]}));const known=new Map(units.flatMap(u=>[0,1,2].flatMap(i=>buildLesson(u,i))).map(q=>[q.id,q]));for(const k of Object.keys(s.errors||{}))if(known.has(k))n.errors[k]=known.get(k);if(!confirm(store.user?'¿Reemplazar el progreso A1 de tu cuenta por esta copia?':'¿Reemplazar el progreso A1 de este navegador por esta copia?'))return;if(!await store.replace(n))return toast('No se pudo importar en tu cuenta. Conserva la copia e inténtalo de nuevo.');state=hydrateProgress(store.getState());session=null;renderProgress();toast('Progreso importado.');}catch{toast('No se pudo importar: selecciona una copia JSON válida de Hello A1.');}}
window.addEventListener('hashchange',routeChanged);
window.addEventListener('pagehide',stopAudio);

function accountBadge(){const a=store.snapshot();if(!a.user)return 'Entrar con Google';const labels={loading:'Cargando…',syncing:'Guardando…',pending:'Pendiente',saved:'Guardado',error:'Revisar guardado'};return `${esc((a.user.displayName||'Mi cuenta').split(' ')[0])}<small>${labels[a.status]||'Mi cuenta'}</small>`;}
function accountStatus(){const a=store.snapshot();const labels={connecting:'Preparando el acceso…','not-configured':'El acceso a cuentas todavía no está activado. Puedes estudiar como invitado.',guest:'Modo invitado: guardado en este navegador.','signing-in':'Completa el acceso en la ventana de Google.',loading:'Recuperando tu progreso…',syncing:'Sincronizando tu progreso…',pending:'Tienes cambios pendientes de subir.',saved:'Tu progreso está sincronizado con tu cuenta.',error:'No se ha completado la sincronización.'};return a.message||labels[a.status]||'';}
function googleButton(){const a=store.snapshot();return `<button class="btn google-button" data-action="google-login" ${!a.configured||['connecting','signing-in'].includes(a.status)?'disabled':''}>Continuar con Google</button>`;}
function renderHome(){const a=store.snapshot();shell(`<section class="new-home-hero"><div><span class="pill blue">INGLÉS A1 · PARA HISPANOHABLANTES</span><h2>Un poco cada día.<br><em>Mucho por descubrir.</em></h2><p>Construye tus primeras conversaciones con explicaciones claras, práctica de voz y un camino que puedes seguir a tu ritmo.</p><div class="button-row">${a.user?'<button class="btn primary" data-action="nav" data-to="route">Continuar mi aprendizaje</button>':googleButton()}<button class="btn ${a.user?'ghost':'primary'}" data-action="nav" data-to="route">${a.user?'Ver todas las unidades':'Empezar como invitado'}</button></div><p class="home-account-note" role="status">${esc(accountStatus())}</p><a class="text-link" href="#account">¿Cómo se guarda mi progreso?</a></div><img src="assets/hello-robot.webp" alt="Personaje del curso con auriculares, un libro y un lápiz" width="1536" height="1024"></section><div class="home-numbers"><div><strong>24</strong><span>unidades A1</span></div><div><strong>72</strong><span>lecciones a tu ritmo</span></div><div><strong>504</strong><span>actividades para practicar</span></div></div><div class="three-cards"><section class="panel"><span class="quick-icon blue">${icon('book')}</span><h3>Comprende y practica</h3><p>Gramática en español, vocabulario, lecturas, diálogos y ejercicios con explicación.</p></section><section class="panel"><span class="quick-icon orange">${icon('mic')}</span><h3>Escucha tu inglés</h3><p>Escucha frases, repítelas y compara qué palabras reconoce el navegador.</p></section><section class="panel"><span class="quick-icon blue">${icon('chart')}</span><h3>Continúa donde estés</h3><p>Cuando el acceso esté activado, entra con la misma cuenta de Google en otro dispositivo para recuperar tu avance.</p></section></div><section class="panel home-path"><div><span class="eyebrow">TU PRIMER NIVEL</span><h2>De “hello” a tu vida en inglés.</h2><p>Presentarte, hablar de tu día, pedir comida, comprar y desenvolverte en situaciones sencillas.</p></div><a href="#route" class="btn primary">Explorar mi ruta A1</a></section>`, 'Tu siguiente paso empieza aquí.','HELLO ENGLISH');}
function renderAccount(){const a=store.snapshot();shell(`<div class="account-layout"><section class="panel account-main"><span class="account-avatar">${a.user?esc((a.user.displayName||'T')[0].toUpperCase()):icon('globe')}</span><h2>${a.user?'Hola, '+esc(a.user.displayName||'estudiante'):'Tu inglés, siempre contigo'}</h2>${a.user?`<p>${esc(a.user.email)}</p><span class="pill blue">CUENTA DE GOOGLE</span>`:'<p>Entra con Google para guardar tu progreso y continuar en otro dispositivo. También puedes estudiar sin cuenta.</p>'}<div class="account-status ${a.status==='error'?'is-error':''}" role="status">${esc(accountStatus())}</div>${a.user?`<div class="button-row"><button class="btn primary" data-action="nav" data-to="route">Volver a mis lecciones</button><button class="btn soft" data-action="sync-account" ${['syncing','loading'].includes(a.status)?'disabled':''}>Sincronizar ahora</button></div>${a.lastSynced?`<p class="tiny">Última conexión confirmada: ${esc(new Date(a.lastSynced).toLocaleString('es'))}</p>`:''}<button class="btn ghost" data-action="google-logout">Cerrar sesión</button>`:`<div class="button-row">${googleButton()}<button class="btn soft" data-action="nav" data-to="route">Seguir como invitado</button></div>`}<p class="tiny">Google gestiona el acceso. Consulta <a href="#library/privacy">cómo se guardan tus datos</a>.</p></section><aside><section class="panel"><h3>Dos maneras de aprender</h3><p><b>Invitado:</b> tu progreso se queda en este navegador.</p><p><b>Cuenta:</b> tus avances se guardan en la nube cuando hay conexión. Usa la misma cuenta en tu móvil y computadora.</p></section>${a.user&&a.guestAvailable?`<section class="panel"><h3>Ya habías empezado aquí</h3><p>Hay progreso de invitado en este navegador. Puedes añadirlo a tu cuenta si es tuyo.</p><button class="btn soft full" data-action="import-guest">Añadir mi progreso de invitado</button></section>`:''}<section class="panel"><h3>Tu copia, contigo</h3><p>Puedes descargar una copia de tus avances, importarla o reiniciar el curso desde Mi progreso.</p><a class="text-link" href="#progress">Gestionar mi progreso</a></section></aside></div>`,'Mi cuenta','APRENDE · GUARDA · CONTINÚA');}

window.HelloA1={normalize,compareSpeech,buildLesson,numberWords,stats:()=>({units:units.length,lessons:units.length*3,activities:units.flatMap(u=>[0,1,2].flatMap(i=>buildLesson(u,i))).length,vocabulary:vocab.length}),getProgress:()=>({completed:done(),xp:state.xp,unitProgress:units.map(u=>({unit:u.id,completed:uDone(u.id)}))})};

knownQuestions=new Map(units.flatMap(u=>[0,1,2].flatMap(i=>buildLesson(u,i))).map(q=>[q.id,q]));
state=hydrateProgress(store.getState());
let previousScope=store.scope;
store.subscribe((a,meta)=>{const changed=!equal(cleanProgress(state),a.progress);state=hydrateProgress(a.progress);storageOK=a.localAvailable;const scopeChanged=a.scope!==previousScope;previousScope=a.scope;
 if(scopeChanged){session=null;stopAudio();nav(a.user?'account':'home');return;}
 document.querySelectorAll('[data-account-badge]').forEach(el=>{el.innerHTML=accountBadge();});
 if(meta.kind==='initial')return;
 if(['home','account'].includes(current)){if(current==='home')renderHome();else renderAccount();}
 else if(meta.kind==='remote'&&changed&&['route','progress','review'].includes(current))routeChanged();
});
routeChanged();
}

